/** A transition in plain words — the process view (ADR 0031). */
export type ProcessStep = {
  id: string;
  from: string;
  from_display?: string;
  to: string;
  to_display?: string;
  actor: string;
  actor_type: "agent" | "human" | "system" | "job" | "decision" | "release_train";
  who: string;
  /** What the step writes; for a decision step (ADR 0121), each question's `<name>` and `<name>_confidence`, which a `when` compares. */
  outputs?: Array<string>;
  gates?: Array<{
    name?: string;
    summary?: string;
    /** The thresholds the guarantee applies (the platform's defaults when the workflow sets none), and how long an asynchronous one waits. */
    detail?: string | null;
    /** True for a guarantee that waits for an outside event (CI, review, scans) up to the transition's `timeout_hours`. */
    asynchronous?: boolean;
  }>;
  on_fail?: string | null;
  on_reject?: string | null;
  timeout_hours?: number | null;
  /** The governed action the transition proposes */
  action?: string | null;
  /** The task a person does */
  task?: string | null;
  sentence: string;
  /** The registry agent the actor names, `slug` or `slug@N` (ADR 0033); null for an implicit playbook actor and for any actor that is not an agent. */
  agent?: string | null;
  /** The role of an agent, job or decision actor. */
  role?: string | null;
  /** The model or profile of an agent actor, as written (`profile:standard`); the catalogue entry of a decision actor (`platform/decide`). */
  model?: string | null;
  /** The group of a human actor. */
  group?: string | null;
  /** The person a human actor names, by e-mail (ADR 0153): asked first, before the group. */
  user?: string | null;
  /** The SLA of a human actor. */
  sla_hours?: number | null;
  /** The argv of a job actor. */
  command?: Array<string> | null;
  /** The image name of a job actor. */
  image?: string | null;
  /** The documents the step reads (`inputs:` of the transition). */
  inputs?: Array<string>;
  /** The declared file type of an output (ADR 0049); an output not listed is inline, markdown or JSON. */
  output_types?: {
    [key: string]: string;
  };
  /** True for an agent or job step whose transition carries a gate that reads the diff: it changes the work item's branch. */
  writes_branch?: boolean;
};

/** A typed operation. `op` says which one; the other fields depend on it (`name`, `spec`, `from`, `to`, `id`, `transition`, `field`, `value`, `raw`, `unset`, `gate`, `text`, `index`, `style`, `swap`). `set_workflow` edits `metadata.description`, `metadata.inputs`, `metadata.catalogue` and `initial` (ADR 0112). `style: block` writes a collection value as indented lines; `swap` with `text` puts a key's exact lines back in place of its current ones. */
export type WorkflowOperation = {
  op: "add_state" | "remove_state" | "rename_state" | "set_state" | "add_transition" | "remove_transition" | "set_transition" | "add_gate" | "remove_gate" | "add_actor" | "remove_actor" | "set_actor" | "set_workflow";
  style?: "flow" | "block";
  swap?: boolean;
  [key: string]: unknown;
};

export type WorkflowEditRequest = {
  yaml: string;
  operations: Array<WorkflowOperation>;
};

export type WorkflowEditResult = WorkflowValidation & {
  yaml: string;
  /** unified diff from the original text to the edited text */
  diff: string;
  inverse: Array<WorkflowOperation>;
  /** what an operation changes beyond the text (a state with effects renamed…) */
  notices: Array<string>;
};

export type AgentLimits = {
  max_turns?: number | null;
  max_minutes?: number | null;
};

export type AgentBudget = {
  run_usd?: number | null;
  daily_usd?: number | null;
  monthly_usd?: number | null;
};

/** What an agent version is; it never changes (ADR 0033). */
export type AgentSpec = {
  instructions?: string;
  model?: string | null;
  /** the ACP coding agent that carries the version; set only with an `acp` runtime (or none) */
  backend?: string | null;
  /** How the version runs (ADR 0063). Absent means an `acp` runtime, the coding agent named by `backend`. `a2a` is a remote agent (ADR 0062). `prompt`, `voice` and `hosted` are ADR 0080's: instructions and tools with no code, the same spoken, and the agent's own container serving Foundry's hosted contract. */
  runtime?: AcpRuntime | CodeRuntime | A2aRuntime | PromptRuntime | VoiceRuntime | HostedRuntime;
  limits?: AgentLimits;
  budget?: AgentBudget;
  skills?: Array<{
    slug: string;
    version?: number | null;
  }>;
  mcp_servers?: Array<{
    connector: string;
    /** operation names or `prefix_*` patterns; an object binds the call's arguments (ADR 0128) */
    tools?: Array<string | AgentToolGrant>;
  }>;
  /** the knowledge bases the agent reads (ADR 0051); each must be served to the run's project */
  knowledge?: Array<{
    slug: string;
  }>;
  /** The agent's eval suite (S32-03): every case of the published version and of the new one must pass before the new one is published */
  evals?: Array<AgentEvalCase>;
  /** SUPERSEDED by `memories` (S40-11): read only when `memories` is absent. Whose memory a run reads and writes (S32-02): the project's shared memory, the agent's own within the project, or none */
  memory?: "none" | "project" | "agent";
  /** The memories a run reads and writes (S40-11, ADR 0075), in precedence order (earlier wins). At most 8, no duplicates, at most one `write` (the target of the run's lessons, findings and proposals; a global target only ever receives proposals). Absent means: derive from `memory`. Sent together with a non-default `memory` it is a 422. */
  memories?: Array<AgentMemoryBinding> | null;
  network?: AgentNetwork;
  /** The workspace a run gets (S51-03, ADR 0119); the repository is the project's. `none`: nothing is cloned and the repository's host is not on the run's network. `read`: the repository is cloned and no file of it may be written (only the step's deliverables in `.choregos/outputs/`). `write`: today's run. Absent (left out of the stored spec, so no digest moves): `write`, or the `hosted` runtime's `workspace`. Refused with an `a2a` runtime, and with a `hosted` one when it differs from `runtime.workspace`. */
  workspace?: "none" | "read" | "write" | null;
  /** The agent's measured default for tool scripts (ADR 0122 §9, S57-15). Absent (left out of the stored spec, so no digest moves): no default. Refused with an `a2a` runtime. */
  tools?: AgentTools | null;
  /** The language a person reads the agent's output in (ADR 0126): a language tag, a primary subtag optionally followed by a region (`fr`, `de`, `pt-BR`). The platform's frame asks the agent to write its summary, documents, questions and findings in it; the keys, identifiers and enum values of the result contract stay as specified. Absent (left out of the stored spec, so no digest moves) or `en`: English, as before. */
  language?: string | null;
};

/** How a run of this agent calls its tools by default (ADR 0122 §9, S57-15): a default, never a right. Strictest first, the deployment's brake, the organisation's switch (its `tool_scripts` setting, else the deployment's default), the organisation's ceiling, and the project's policy whenever it says something for the stage's role (`tools.per_role.<role>.scripts`, else `tools.scripts`) decide before it; a policy that says nothing leaves it. An eval cell's door ignores it. Since ADR 0127 it also names the tools a run is offered, source by source: a list that is present, even empty, closes its source (a run gets what the version names AND its project and the deployment allow); a list that is absent leaves that source to the project, as before. */
export type AgentTools = {
  /** `offer`: a run is offered tool scripts unless something above says otherwise; `off`: no default, as absent */
  scripts?: "off" | "offer";
  /** The deployment catalogue's tools the version uses (ADR 0014), by name or as `group:<name>` (ADR 0127). Absent: every tool the project's `tools` and `groups` open */
  catalogue?: Array<string> | null;
  /** The extensions whose tools the version uses, by name (ADR 0127). Absent: every extension's tools */
  extensions?: Array<string> | null;
  /** The governed web tools the version uses: `fetch` (ADR 0070), `search` (ADR 0083) (ADR 0127). Absent: each one whenever the run's network or the project offers it */
  web?: Array<"fetch" | "search"> | null;
};

/** A coding agent that speaks ACP (ADR 0002), one of the backends the runner ships. */
export type AcpRuntime = {
  kind: "acp";
  backend?: string | null;
};

/** An agent written in code (ADR 0063) - an ACP agent in an image the operator named, built from the runner image. */
export type CodeRuntime = {
  kind: "code";
  /** the NAME of an image of the operator's `CHOREGOS_AGENT_IMAGES` map, never an image reference */
  image: string;
  /** the argv the runner starts in the image; it speaks ACP on stdio */
  command: Array<string>;
  /** the model API the code calls through the gateway */
  api_format?: "openai" | "anthropic";
};

/** An agent that runs elsewhere and is reached over A2A (ADR 0062), e.g. Atlassian's Rovo. The step runs in the runner pod. `model` and `backend` of the spec must be empty, and so must skills, knowledge and MCP servers. */
export type A2aRuntime = {
  kind: "a2a";
  card_url: string;
  /** one skill of the card the step asks for */
  skill?: string | null;
  /** the organisation's remote credential; absent only for a card that asks for none */
  credential?: string | null;
  timeout_minutes?: number;
  declared_cost?: A2aDeclaredCost;
  input?: "text" | "text+files";
  /** filled by the API at publication: the card as it was read; the runner refuses a card that changed */
  pinned_card?: A2aPinnedCard | null;
};

/** A prompt agent (ADR 0080): the spec's instructions, model, MCP servers and knowledge, run as a tool loop by the platform - no coding agent, no container code. `backend` must be empty. */
export type PromptRuntime = {
  kind: "prompt";
  max_output_tokens?: number | null;
  tool_choice?: "auto" | "required" | "none";
  /** `json_object` asks the model for a JSON object, read as the step's outputs */
  response_format?: "text" | "json_object";
};

/** A voice-based prompt agent (ADR 0080): a realtime model spoken to over `GET /agents/{slug}/realtime`. `model` must be a catalogue model marked `realtime`; `backend` and `skills` must be empty. It runs only as a session, never as a workflow step. */
export type VoiceRuntime = {
  kind: "voice";
  voice?: string;
  audio?: VoiceAudio;
  /** what the agent says first, before the caller speaks */
  greeting?: string | null;
  turn_detection?: "server_vad" | "none";
  max_session_minutes?: number;
};

export type VoiceAudio = {
  format?: "pcm16";
  sample_rate?: 16000 | 24000;
  channels?: 1;
};

/** A hosted agent (ADR 0080): the agent's own container, from an image or built from a source zip, serving Foundry's hosted contract (`GET /readiness`, `POST /responses` and/or `POST /invocations`, optionally `GET /invocations_ws`) on `port`, beside the runner in the run's pod. It holds no credential: the model, the MCP servers and the internet are reached through the runner's loopback listeners. `backend` and `skills` must be empty. */
export type HostedRuntime = {
  kind: "hosted";
  source: HostedImageSource | HostedZipSource;
  protocols?: Array<"responses" | "invocations" | "invocations_ws">;
  /** the port the container listens on; 4001-4003 are the runner's loopback listeners and are refused */
  port?: number;
  readiness_timeout_s?: number;
  termination_grace_s?: number;
  /** `none`: the repository is not mounted; `read`: read-only; `write`: the container changes it and the runner commits and pushes */
  workspace?: "none" | "read" | "write";
  /** non-secret variables; names are upper-case and the `CHOREGOS_`, `FOUNDRY_`, `OPENAI_`, `ANTHROPIC_` prefixes and the proxy variables are refused */
  env?: {
    [key: string]: string;
  };
  /** filled by the platform for a zip source, never by the caller */
  build?: HostedBuild | null;
};

export type HostedImageSource = {
  type: "image";
  /** an image reference under a prefix of the operator's `CHOREGOS_HOSTED_REGISTRIES` */
  ref: string;
  /** filled by the API at publication: what `ref` resolved to; runs pull `ref@digest` */
  digest?: string | null;
};

export type HostedZipSource = {
  type: "zip";
  /** the uploaded source (`POST /orgs/{org}/hosted-sources`) */
  sha256: string;
  runtime: "python_3_12" | "python_3_13" | "python_3_14" | "node_22" | "dotnet_10";
  /** the argv started in the built image, e.g. [python, main.py] */
  entry_point: Array<string>;
  /** `remote_build` installs the declared dependencies at build time; `bundled`: the zip carries them */
  dependency_resolution?: "remote_build" | "bundled";
};

/** An uploaded source zip (ADR 0080 §9). */
export type HostedSource = {
  sha256: string;
  size_bytes: number;
  files: Array<string>;
  /** the file at the root that declares the dependencies `remote_build` installs: `requirements.txt` or `pyproject.toml` (Python), `package-lock.json` beside its `package.json` (Node), the one `*.csproj` (.NET); null when there is none */
  dependencies?: string | null;
};

/** The build of a zip source (ADR 0080), at publication, keyed by its inputs: the same inputs never build twice. */
export type HostedBuild = {
  status: "pending" | "building" | "ready" | "failed";
  key: string;
  /** the built image, `ref@sha256:...`, once ready */
  image?: string | null;
  error?: string | null;
  provenance?: {
    [key: string]: string;
  };
};

/** One turn of a direct conversation (ADR 0080 §10). The agent's spec decides the model, the instructions and the tools. */
export type AgentResponseCreate = {
  /** the project the session works in: its budget pays, its grants bound the tools */
  project: string;
  input: string | Array<AgentInputMessage>;
  session_id?: string | null;
  stream?: boolean;
  /** the caller's cap on the whole session, when it opens; the project's budgets still bind */
  max_usd?: number | null;
};

export type AgentInputMessage = {
  role?: "user";
  content: string;
};

export type AgentOutputText = {
  type?: "output_text";
  text: string;
};

export type AgentOutputMessage = {
  type?: "message";
  role?: "assistant";
  content: Array<AgentOutputText>;
};

export type AgentResponseError = {
  /** `budget_exceeded`, `model_error`, `max_turns` */
  code: string;
  message: string;
};

export type AgentResponseUsage = {
  input_tokens?: number;
  output_tokens?: number;
  turns?: number;
  tool_calls?: number;
};

/** The part of the Responses API's shape a client reads. */
export type AgentResponse = {
  id: string;
  object?: "response";
  session_id: string;
  status: "completed" | "failed";
  output?: Array<AgentOutputMessage>;
  output_text?: string;
  usage?: AgentResponseUsage;
  error?: AgentResponseError | null;
  /** The memory spaces the turn wrote or proposed in (a conversation with an assistant). */
  memory_updated?: Array<string>;
};

/** A `response.output_text.delta` event. */
export type AgentDelta = {
  type?: "response.output_text.delta";
  response_id: string;
  delta: string;
};

export type AgentSessionEvent = {
  seq: number;
  type: string;
  ts: string;
  payload?: {
    [key: string]: unknown;
  };
};

/** A direct conversation with an agent (ADR 0080 §10), next to runs: its key, its spend and its transcript. */
export type AgentSession = {
  id: string;
  agent: string;
  agent_version: number;
  project: string;
  status: "open" | "idle" | "closed" | "failed";
  reason?: string | null;
  model: string;
  responses: number;
  tool_calls: number;
  cost_usd: number;
  created_at: string;
  expires_at: string;
  closed_at?: string | null;
  events?: Array<AgentSessionEvent>;
};

/** A row of the caller's conversations (ADR 0134). `idle` is inactive past its `idle_close_minutes`: a new message reopens it. */
export type ConversationSummary = {
  id: string;
  /** cut from the first message; null before it */
  title?: string | null;
  agent: string;
  agent_version: number;
  installation_id?: string | null;
  /** the slug of the organisation the conversation belongs to */
  org?: string | null;
  /** the slug of the assistant's installation in that organisation, when it is one */
  assistant?: string | null;
  status: "open" | "idle" | "closed" | "failed";
  turns: number;
  cost_usd: number;
  /** the conversation's own cap */
  max_usd?: number | null;
  created_at: string;
  last_activity_at: string;
};

export type ConversationMessage = {
  role: "user" | "assistant";
  content: string;
};

/** A conversation with what was said in it; the system message and the tool traffic are not shown. */
export type Conversation = ConversationSummary & {
  context?: {
    [key: string]: unknown;
  } | null;
  messages?: Array<ConversationMessage>;
};

export type ConversationPage = {
  items: Array<ConversationSummary>;
  meta: PageMeta;
};

/** One turn of a conversation: what the person says. */
export type ConversationMessageCreate = {
  input: string;
  stream?: boolean;
};

/** A thumb on one answer of a session (S63-17, ADR 0140). */
export type ConversationFeedbackCreate = {
  rating: "up" | "down";
  comment?: string | null;
  /** The answer, by its 1-based position among the session's responses; absent: the latest */
  response?: number | null;
};

export type ConversationFeedback = {
  id: string;
  session_id: string;
  agent: string;
  /** The agent revision that gave the answer */
  agent_version: number;
  response: number;
  rating: "up" | "down";
  comment?: string | null;
  /** `proposed` when the thumb down proposed a candidate case to the agent's owners */
  candidate_status?: string | null;
  created_at: string;
};

/** A candidate eval case a thumb down proposed, as the agent's owners read it: pseudonymised, with no author and no raw comment. It is in no suite until an owner adds it. */
export type ConversationCandidate = {
  id: string;
  agent: string;
  agent_version: number;
  status: "proposed" | "accepted" | "dismissed";
  /** `{case, observed, comment}`: a conversation-evals case without assertions (the accepted one carries its assertions), and what the agent did */
  candidate: {
    [key: string]: unknown;
  };
  created_at: string;
};

/** What an owner adds to a candidate to make it a case: the assertions, and optionally a name, the scripted tool results and the context. */
export type ConversationCandidateAccept = {
  /** a conversation-evals `assert` object */
  assertions: {
    [key: string]: unknown;
  };
  name?: string | null;
  tool_results?: {
    [key: string]: unknown;
  } | null;
  context?: {
    [key: string]: unknown;
  } | null;
};

/** A response a hosted session's person asked for, waiting for the session's pod (S41-11). */
export type AgentSessionTurn = {
  turn_id: string;
  input: string;
  protocol: "responses" | "invocations";
};

export type AgentSessionPodEvent = {
  type: string;
  payload?: {
    [key: string]: unknown;
  };
};

/** How the session's container answered a turn. */
export type AgentSessionTurnResult = {
  status: "answered" | "failed" | "not_ready" | "timeout" | "max_turns" | "budget_exceeded";
  text?: string;
  error?: string | null;
  response_id?: string | null;
  turns?: number;
  tool_calls?: number;
  events?: Array<AgentSessionPodEvent>;
};

/** What a hosted session's caller did on its socket (S41-21): `open`, a text frame `in`, `close`. */
export type AgentSessionSocketFrame = {
  seq: number;
  kind: "open" | "in" | "close";
  text?: string;
  code?: number | null;
};

export type AgentSessionSocketNext = {
  frames?: Array<AgentSessionSocketFrame>;
  /** The journal's `seq` the pod reads after next time. */
  cursor: number;
  /** The last of the container's frames journaled. */
  out_n: number;
};

export type AgentSessionSocketOutFrame = {
  n: number;
  text: string;
};

export type AgentSessionSocketClosed = {
  code: number;
  reason?: string;
};

/** What the container sent on its `/invocations_ws`, and whether it closed it. */
export type AgentSessionSocketOut = {
  frames?: Array<AgentSessionSocketOutFrame>;
  closed?: AgentSessionSocketClosed | null;
  events?: Array<AgentSessionPodEvent>;
};

export type AgentSessionSocketRecorded = {
  out_n: number;
};

/** A tool a run may call, in MCP's `tools/list` format, with what the platform knows of it (ADR 0122). A plugin extension's tool may carry other MCP keys of its own. */
export type RunTool = {
  name: string;
  description: string;
  inputSchema: {
    [key: string]: unknown;
  };
  /** The output schema the operation declares (an organisation connector's, as its server declared it): it describes the `structuredContent` of the tool's `result`, not the API's answer around it. Absent when none is declared. */
  outputSchema?: {
    [key: string]: unknown;
  };
  /** MCP tool annotations. `readOnlyHint` is true only for `x-choregos-access: read`. */
  annotations: {
    readOnlyHint?: boolean;
    [key: string]: unknown;
  };
  /** `read`: a call reads (a catalogue tool — writers are not listed —, a connector read, `web_fetch`, `web_search`, a plugin tool annotated `readOnlyHint`). `write`: a connector write the policy allows, played as a governed action; or a plugin tool that does not say it only reads. `approval`: a connector operation under approval — calling it proposes an action, a person decides. A plugin tool may declare its own, beside its `name`. */
  "x-choregos-access": "read" | "write" | "approval";
  [key: string]: unknown;
};

export type AgentSessionTools = {
  tools?: Array<{
    [key: string]: unknown;
  }>;
};

export type AgentSessionToolCall = {
  arguments?: {
    [key: string]: unknown;
  };
};

export type AgentSessionToolAnswer = {
  /** What the model reads back: the courtier's text, or why the call was refused. */
  text: string;
  /** How the call ended, as `callRunTool`'s `status_code`: the server's status (a provider's answer of 400 or more is an error, its body in `text`), `400` for arguments the tool's schema refuses, `429` past the cap, `451` for a result withheld as a suspected injection (`sandbox.prompt_injection: block`). */
  status_code: number;
  /** The calls the policy's cap (`budgets.tool_calls_per_run`) leaves the session; `null` without a cap. */
  remaining: number | null;
  /** The injection guard's flags on the result (`warn`: the result is in `text`; `block`: it is withheld), empty when none. */
  suspicions: Array<{
    [key: string]: unknown;
  }>;
};

/** What a remote agent costs, as the organisation declares it - A2A reports no figure; booked in the ledger as `external`. */
export type A2aDeclaredCost = {
  per_task_usd?: number | null;
  per_minute_usd?: number | null;
};

export type A2aPinnedCard = {
  url: string;
  protocol_version: string;
  digest: string;
  skills?: Array<string>;
};

/** What the organisation holds to call remote agents. No secret is ever returned - the refresh token lives sealed in the secret store. */
export type RemoteCredential = {
  name: string;
  type: "oauth2_authorization_code" | "bearer" | "none";
  status: "pending" | "connected" | "error" | "revoked";
  /** whose permissions a remote agent acts with: the person who authorised it */
  authorised_as?: string | null;
  scopes?: Array<string>;
  card_url?: string | null;
  host?: string | null;
  created_by?: string | null;
  created_at?: string | null;
  last_refresh_at?: string | null;
  expires_at?: string | null;
  last_error?: string | null;
};

export type RemoteCredentialCreate = {
  name: string;
  type: "oauth2_authorization_code" | "bearer" | "none";
  /** OAuth: the card whose Dynamic Client Registration endpoint the platform registers itself at */
  card_url?: string | null;
  /** bearer: the token, write-only, sealed in the secret store */
  token?: string | null;
};

export type RemoteCredentialAuthorization = {
  /** where to send the administrator's browser (authorization code + PKCE) */
  redirect_url: string;
};

export type RemoteAgentDiscover = {
  card_url: string;
};

export type RemoteSkillInfo = {
  id: string;
  name: string;
  description?: string;
};

export type RemoteCardSummary = {
  name: string;
  description?: string;
  endpoint: string;
  host: string;
  protocol_version: string;
  digest: string;
  skills?: Array<RemoteSkillInfo>;
  /** oauth2_authorization_code, bearer, none: what the card accepts */
  auth_types?: Array<string>;
  scopes?: Array<string>;
  streaming?: boolean;
  /** the card advertises Dynamic Client Registration */
  dcr_available?: boolean;
};

/** What a card says and the registry entry it suggests - nothing is created. */
export type RemoteAgentDiscovery = {
  card: RemoteCardSummary;
  proposed: AgentCreate;
  /** the organisation's credentials of a type the card accepts */
  credentials?: Array<string>;
  /** hosts the project policy must allow (sandbox.network.allow_domains) */
  domains?: Array<string>;
};

/** An image an operator named for code agents. The reference itself is never returned. */
export type AgentImageInfo = {
  name: string;
  /** the reference carries an `@sha256:` digest */
  digest_pinned: boolean;
};

export type AgentMemoryBinding = {
  /** `global`: the organisation's memory; `project`: a memory of whichever project the run is in (`shared`, `own`, or a named one) */
  scope: "global" | "project";
  slug: string;
  mode?: "read" | "write";
};

export type RunMemorySearch = {
  query: string;
  k?: number;
  /** one memory of the run, by label (`global:security-lessons`); absent, all of them */
  memory?: string | null;
};

export type RunMemoryHit = {
  /** the label of the memory the hit came from */
  memory: string;
  kind: string;
  subject: string;
  content: string;
  score?: number | null;
};

export type MemoryStoreUser = {
  agent: string;
  version: number;
};

export type MemoryStore = {
  slug: string;
  display_name: string;
  description?: string | null;
  scope: "global" | "project";
  /** the project's slug, for a project memory */
  project?: string | null;
  /** for a global memory: whose runs read it */
  reach?: "org" | "projects" | null;
  projects?: Array<string>;
  status?: "active" | "archived";
  /** `shared` and `own`: every project has them, they are not rows */
  implicit?: boolean;
  created_by?: string | null;
  created_at?: string | null;
  /** visible agents whose latest version binds it */
  used_by?: Array<MemoryStoreUser>;
};

export type MemoryStoreCreate = {
  slug: string;
  display_name: string;
  description?: string | null;
  reach?: "org" | "projects";
  /** required, non-empty, when `reach` is `projects` */
  projects?: Array<string>;
};

export type ProjectMemoryCreate = {
  slug: string;
  display_name: string;
  description?: string | null;
};

export type MemoryStorePatch = {
  display_name?: string;
  description?: string | null;
  reach?: "org" | "projects";
  projects?: Array<string>;
  status?: "active" | "archived";
};

/** What one agent version may reach (ADR 0070). It can only narrow the project's and the organisation's network: a host they do not allow refuses the publication (422) and the run. */
export type AgentNetwork = {
  /** null: the project's list; []: no internet; a list: only these hosts (`example.com` = it and its subdomains, `*.example.com` = subdomains only) */
  domains?: Array<string> | null;
  /** new connections a run may open to one host per minute */
  per_host_per_minute?: number | null;
  /** false switches the agent CLI's own WebFetch and WebSearch off; null or true: as the policy says */
  builtin_web_tools?: boolean | null;
};

export type RunNetwork = {
  run_id: string;
  allow: Array<string>;
  deny: Array<string>;
  /** hosts the run needs to work at all (the project's repository host) */
  implied: Array<string>;
  per_host_per_minute?: number | null;
  per_run_per_minute?: number | null;
  /** the organisation's cap, counted across all its runs */
  org_per_host_per_minute?: number | null;
  builtin_web_tools: boolean;
  /** always true today: an empty allow list means no internet */
  listed: boolean;
  org: string;
  project: string;
  agent?: string | null;
};

export type NetworkDecisionIn = {
  layer: "proxy" | "runner";
  host: string;
  port?: number;
  decision: "allowed" | "denied" | "rate_limited" | "unreachable";
  reason?: string;
  count?: number;
  bytes_up?: number;
  bytes_down?: number;
  first_at?: string | null;
  last_at?: string | null;
};

export type NetworkDecisionBatch = {
  decisions: Array<NetworkDecisionIn>;
};

export type EffectiveNetwork = {
  allow: Array<string>;
  deny: Array<string>;
  implied: Array<string>;
  per_host_per_minute?: number | null;
  per_run_per_minute?: number | null;
  org_per_host_per_minute?: number | null;
  builtin_web_tools: boolean;
};

export type ProjectNetwork = {
  /** the project's `sandbox.network`, as stored */
  policy: {
    [key: string]: unknown;
  };
  /** the organisation's `network` ceiling, null when it sets none */
  ceiling?: {
    [key: string]: unknown;
  } | null;
  effective: EffectiveNetwork;
  clamps: Array<string>;
};

export type NetworkActivityRow = {
  host: string;
  /** proxy, runner, broker or platform */
  layer: string;
  decision: string;
  reason: string;
  count: number;
  runs: number;
  projects: Array<string>;
  agents: Array<string>;
  last_at: string;
};

export type NetworkActivity = {
  rows: Array<NetworkActivityRow>;
};

/** A deterministic case (ADR 0020, level 1) — the instructions rendered on its sample input contain what they must, and nothing they must not. */
export type AgentEvalCase = {
  name: string;
  input?: AgentSampleInput;
  must_contain?: Array<string>;
  must_not_contain?: Array<string>;
  /** a live case runs as a capped trial on the real model and asserts on the run's result (S40-02d); the level-1 gate leaves it out */
  live?: boolean;
  /** the status the run's result must have */
  expect_status?: "done" | "blocked";
  /** what this case's trial may spend; absent, 0.25 $ */
  max_cost_usd?: number | null;
};

/** A sample work item an agent is tried or evaluated on. */
export type AgentSampleInput = {
  title?: string;
  body?: string;
  /** the work item's fields, rendered as `ticket.fields` (S51-04): `{tracker: {reporter, creator, labels, answers}}` plays a ticket filed from a tracker; absent, `{}` */
  fields?: {
    [key: string]: unknown;
  };
};

export type AgentEvalResult = {
  name: string;
  passed: boolean;
  missing?: Array<string>;
  forbidden?: Array<string>;
  /** the instructions do not render on this input */
  error?: string | null;
};

/** Try a draft version on a sample input, in one project, under a capped budget (S32-03). */
export type AgentTrialCreate = {
  /** the project's slug: its model profiles, backend and tools apply */
  project: string;
  spec: AgentSpec;
  input: AgentSampleInput;
  /** capped at 0.50 $, at the version's budget per run and at the project's budget per work item */
  budget_usd?: number | null;
  /** the agent the draft would become a version of: its published suite is run too */
  agent?: string | null;
};

export type AgentTrial = {
  /** read it at `GET /runs/{id}` */
  run_id: string;
  work_item_id: string;
  project: string;
  budget_usd: number;
  status: string;
  evals?: Array<AgentEvalResult>;
};

/** Labels people find the agent by (S40-10); never part of a version */
export type AgentTags = Array<string>;

export type AgentCreate = {
  /** `new` is reserved: the console's `/agents/new` page would shadow it (422) */
  slug: string;
  /** `remote`: an agent the platform calls over A2A (ADR 0062); it needs an `a2a` runtime */
  kind?: "internal" | "external" | "remote";
  display_name: string;
  description?: string | null;
  spec?: AgentSpec;
  /** a draft is neither pinned nor run until it is activated */
  lifecycle?: "draft" | "active";
  /** who owns the agent (ADR 0061); `platform` is never asked for, a common agent comes from the catalogue */
  scope?: "org" | "project" | "personal";
  /** the project's slug: required for, and only for, a `project` agent */
  project?: string | null;
  tags?: AgentTags;
  /** why version 1 exists; absent, `Created` (S40-12) */
  message?: string | null;
  /** what saving a revision does (ADR 0071); absent, the defaults: it goes to production */
  release_policy?: AgentReleasePolicy | null;
};

export type AgentFork = {
  /** slugs are unique per organisation: a fork takes a new one */
  slug: string;
  display_name?: string | null;
  scope: "org" | "project" | "personal";
  /** required for, and only for, a `project` fork */
  project?: string | null;
  /** the source version to copy; absent, its latest */
  version?: number | null;
  /** why version 1 exists; absent, `Forked from <slug>@<version>` (S40-12) */
  message?: string | null;
};

export type AgentScopeChange = {
  scope: "org" | "project" | "personal";
  /** required for, and only for, a move to a `project` */
  project?: string | null;
};

/** What a fork was copied from, and whether the source moved on since (ADR 0061). */
export type AgentUpstream = {
  slug: string;
  /** the version the fork copied */
  version: number;
  /** absent when the source is no longer visible to the caller */
  scope?: "platform" | "org" | "project" | "personal" | null;
  latest_version?: number | null;
  /** the source published a version newer than the one copied */
  behind?: boolean;
  /** false when the source is deleted or not visible to the caller */
  available?: boolean;
};

/** What the caller may do with an agent, decided by the server (ADR 0061). */
export type AgentPermissions = {
  /** publish a version, edit it, move it through its life */
  publish?: boolean;
  /** suspend, revoke, change its owner, attach clients */
  manage?: boolean;
  /** pin it on a project the caller owns */
  pin?: boolean;
  /** send a revision to testing or production, roll back (ADR 0071) */
  release?: boolean;
  fork_scopes?: Array<"org" | "project" | "personal">;
};

export type AgentDraftRequest = {
  display_name: string;
  /** what the agent is for; data for the drafting model */
  description: string;
};

/** A proposal that is never saved; the builder is pre-filled with it and a person creates the agent. */
export type AgentDraft = {
  display_name: string;
  slug: string;
  description: string;
  spec: AgentSpec;
  sample: AgentSampleInput;
  /** what the platform changed or dropped in the model's answer */
  notes?: Array<string>;
  /** the model that drafted it */
  model: string;
};

/** An agent the platform's catalogue offers (ADR 0040), and its state in the organisation. */
export type AgentCatalogueEntry = {
  slug: string;
  kind: "internal" | "external" | "remote";
  display_name: string;
  description?: string | null;
  /** the package role it plays (`implement`, `review`…), or `external` for a client */
  role: string;
  summary: string;
  /** the catalogue's version of the entry */
  version: number;
  skills?: Array<string>;
  /** labels the entry carries (S40-10): installed with the agent, added on upgrade, never removed */
  tags?: Array<string>;
  /** an external client's id on the AI clients page */
  client?: string | null;
  /** `cloud`: it calls from its vendor's cloud */
  reach?: "always" | "cloud" | null;
  installed: boolean;
  installed_version?: number | null;
  /** an agent of the organisation has this name and does not come from the catalogue */
  own_agent?: boolean;
  /** the scope of the agent of this name in the organisation, if any (ADR 0061) */
  scope?: "platform" | "org" | "project" | "personal" | null;
  update_available?: boolean;
  /** false for a client the door does not accept yet (OAuth, registered client, https) */
  offered?: boolean;
  unavailable_reason?: string | null;
};

export type AgentCatalogueConnect = {
  /** a `mcp:read` token instead of `mcp:write` */
  read_only?: boolean;
  expires_in_days?: number | null;
};

export type AgentCatalogueConnection = {
  agent: Agent;
  /** returned once; none for a client that signs in with OAuth */
  token?: ApiTokenCreated | null;
  oauth_client_id?: string | null;
};

export type AgentCatalogueInstall = {
  /** already installed: publish the catalogue's version as the next one */
  upgrade?: boolean;
};

export type AgentPatch = {
  display_name?: string | null;
  description?: string | null;
  status?: "active" | "suspended" | "revoked" | null;
  expires_at?: string | null;
  /** replaces the agent's tags; absent or null leaves them as they are (S40-10) */
  tags?: AgentTags | null;
};

export type AgentVersion = {
  version: number;
  spec: AgentSpec;
  checksum: string;
  created_by?: string | null;
  created_at?: string | null;
  /** why the version exists, in its author's words (S40-12); null for a version published before messages or through the bare-spec endpoint */
  message?: string | null;
  /** the version this one copies, when it is a restore */
  restored_from?: number | null;
  /** the slugs of the projects the caller may see that pin this version */
  pinned_by?: Array<string>;
  /** what a run of this version binds: `spec.memories`, or what the legacy `spec.memory` means (S40-11) */
  effective_memories?: Array<AgentMemoryBinding>;
  /** the channels this revision sits on now (ADR 0071) */
  channels?: Array<"stable" | "candidate">;
};

export type AgentVersionPublish = {
  spec: AgentSpec;
  /** what changed and why */
  message: string;
  /** the latest version the author started from (0 for an agent with none) */
  base_version: number;
};

export type AgentVersionRestore = {
  /** absent, `Restore vN` */
  message?: string | null;
  /** the latest version the author saw */
  base_version: number;
};

export type Agent = {
  slug: string;
  kind: "internal" | "external" | "remote";
  display_name: string;
  description?: string | null;
  tags?: AgentTags;
  status: string;
  owner?: string | null;
  expires_at?: string | null;
  revoked_at?: string | null;
  latest_version: number;
  created_at?: string | null;
  versions?: Array<AgentVersion> | null;
  /** where the agent is in its life (S32-04); apart from the operational status */
  lifecycle?: "draft" | "active" | "deprecated" | "retired";
  retired_at?: string | null;
  last_run_at?: string | null;
  /** no run for 60 days (since its creation if it never ran) */
  unused?: boolean;
  /** who owns it (ADR 0061) */
  scope?: "platform" | "org" | "project" | "personal";
  /** the slug of its project, for a `project` agent */
  project?: string | null;
  /** set on a fork */
  forked_from?: AgentUpstream | null;
  can?: AgentPermissions;
  /** the server's sentence for what the caller may not do: shown as is, never guessed from roles */
  cannot_reason?: string | null;
  /** the revision in production (ADR 0071) */
  stable_version?: number | null;
  /** the revision in testing */
  candidate_version?: number | null;
  /** the share of work items, of projects that follow production, served the candidate */
  candidate_percent?: number;
  candidate_since?: string | null;
  release_policy?: AgentReleasePolicy;
  /** the release waiting for approval */
  pending_release?: AgentRelease | null;
  social?: AgentSocial;
};

/** The counters of an agent and what the caller does with it (ADR 0152). `forks` counts the forks the caller may see. */
export type AgentSocial = {
  watchers?: number;
  stars?: number;
  forks?: number;
  /** the caller's watch level */
  watching?: "all" | "releases" | null;
  starred_by_me?: boolean;
};

export type AgentWatchPut = {
  level?: "all" | "releases";
};

export type AgentForkEntry = {
  slug: string;
  display_name: string;
  scope: "platform" | "org" | "project" | "personal";
  project?: string | null;
  owner?: string | null;
  created_at?: string | null;
  /** the version of the source this fork copied */
  forked_from_version?: number | null;
  latest_version: number;
  /** its own versions go past the first */
  diverged?: boolean;
  lifecycle?: "draft" | "active" | "deprecated" | "retired";
};

export type AgentForkList = {
  items: Array<AgentForkEntry>;
};

export type AgentNotification = {
  id: string;
  kind: "version_published" | "production_moved" | "candidate_started" | "candidate_promoted" | "candidate_withdrawn" | "rolled_back" | "forked" | "lifecycle_changed";
  agent: string;
  /** the fork a `forked` item names */
  fork?: string | null;
  actor?: string | null;
  version?: number | null;
  previous_version?: number | null;
  /** what the move was (`promote`, `rollback`, `publish`) or the lifecycle reached */
  detail?: string | null;
  created_at: string;
  read_at?: string | null;
};

export type AgentNotificationList = {
  items: Array<AgentNotification>;
  /** unread items the caller may still read */
  unread?: number;
};

export type AgentNotificationsRead = {
  updated: number;
};

export type AgentReleaseDecision = {
  decision: "approve" | "reject" | "cancel";
  /** required for a rejection */
  reason?: string | null;
};

/** What a revision must satisfy before it reaches production; a rollback skips them. */
export type AgentStableGates = {
  /** the revision must be the current candidate */
  require_candidate?: boolean;
  /** finished runs of the candidate since it became the candidate */
  min_candidate_runs?: number;
  min_success_rate?: number | null;
  min_soak_hours?: number | null;
  /** how recent the person's sign-in must be */
  step_up_minutes?: number;
  /** the latest finished live evaluation of the revision must score at least this; a rollback skips it */
  min_live_score?: number | null;
  /** people other than the requester who must approve a promotion before production moves; a rollback never waits (ADR 0071) */
  approvals?: number;
  /** neither the requester nor the revision's author may approve */
  separation_of_duties?: boolean;
};

/** What a revision must satisfy before it is sent to testing by hand (saving it to testing under `on_publish` is the owner's stated policy and is not gated). */
export type AgentCandidateGates = {
  min_live_score?: number | null;
};

export type AgentEvaluationCreate = {
  /** the project's slug: the trials run there (needs the right to try an agent in it) */
  project: string;
};

/** A live evaluation of one revision, judged from its trial runs as they stand. `not_run` (no model to call) is never `passed`. */
export type AgentEvaluation = {
  id: string;
  version: number;
  project: string;
  /** `passed` when every case finished and the score reaches the policy's minimum (every case when none is set) */
  status: "running" | "passed" | "failed" | "not_run";
  /** passed cases over live cases */
  score?: number | null;
  /** the most the evaluation may spend in all */
  budget_usd: number;
  started_by?: string | null;
  started_at: string;
  cases?: Array<{
    name: string;
    /** read it at `GET /runs/{id}` */
    run_id: string;
    status: "running" | "passed" | "failed" | "not_run";
    passed?: boolean | null;
    budget_usd?: number;
    cost_usd?: number;
    /** why it failed or did not run */
    reason?: string | null;
  }>;
};

/** What saving a revision does, and the gates of production (ADR 0071). `on_publish: stable` cannot be combined with `require_candidate` or a candidate threshold (422): a revision published straight to production is never a candidate. */
export type AgentReleasePolicy = {
  /** `stable`: a saved revision goes to production (the behaviour before channels); `candidate`: to testing; `none`: nowhere */
  on_publish?: "stable" | "candidate" | "none";
  stable?: AgentStableGates;
  candidate?: AgentCandidateGates;
  /** the most one live evaluation may spend in all */
  max_eval_usd?: number;
};

export type AgentReleaseCreate = {
  channel: "candidate" | "stable";
  /** `null` with `candidate` withdraws the candidate; `null` with `stable` releases the current candidate */
  version?: number | null;
  /** candidate only: the share of work items served the candidate; absent keeps the current share (0 for a new candidate) */
  percent?: number | null;
  reason?: string | null;
};

export type AgentReleaseCheck = {
  /** eval_suite, newer_than_production, is_candidate, candidate_runs, candidate_success_rate, soak, previously_in_production, human_session, fresh_authentication, live_eval, conversation_suite (the assistant's conversation suites, production only), approvals (informational: how many people must approve) */
  name: string;
  required?: boolean;
  /** null: not applicable */
  passed?: boolean | null;
  detail?: string | null;
};

export type AgentRelease = {
  id: string;
  agent: string;
  channel: "candidate" | "stable";
  kind: "publish" | "promote" | "rollback" | "withdraw" | "baseline";
  version?: number | null;
  previous_version?: number | null;
  percent?: number | null;
  /** `pending_approval`: waits for `approvals_required` people; `superseded`: production moved meanwhile */
  status: "done" | "pending_approval" | "rejected" | "cancelled" | "superseded";
  /** how many other people must approve before production moves; 0 for a release that did not wait */
  approvals_required?: number;
  decisions?: Array<{
    by: string;
    decision: "approve" | "reject" | "cancel";
    reason?: string | null;
    at: string;
    /** how old the person's sign-in was when they decided */
    auth_age_seconds?: number | null;
  }>;
  requested_by?: string | null;
  requested_at: string;
  done_at?: string | null;
  reason?: string | null;
  /** the checks as they were evaluated (a snapshot) */
  checks?: Array<AgentReleaseCheck>;
};

export type AgentChannelStats = {
  version: number;
  /** finished runs */
  runs?: number;
  succeeded?: number;
  failed?: number;
  success_rate?: number | null;
  since?: string | null;
};

export type AgentReleaseReadiness = {
  version: number;
  channel: "candidate" | "stable";
  kind: "publish" | "promote" | "rollback" | "withdraw" | "baseline";
  /** every required check passes */
  ready: boolean;
  checks?: Array<AgentReleaseCheck>;
  candidate?: AgentChannelStats | null;
  production?: AgentChannelStats | null;
};

export type AgentExposure = {
  stable_version?: number | null;
  candidate_version?: number | null;
  candidate_percent?: number;
  projects?: Array<{
    project: string;
    source: "pin" | "pin_channel" | "project_channel";
    channel?: "stable" | "candidate" | null;
    version: number;
  }>;
};

export type ProjectAgentChannel = {
  /** which channel of the agents the project runs when it pins nothing */
  channel: "stable" | "candidate";
};

export type AgentLifecycleChange = {
  to: "active" | "deprecated" | "retired";
  /** retire although runs of the agent are in flight */
  force?: boolean;
  reason?: string | null;
};

export type AgentLifecycleResult = {
  agent: Agent;
  revoked_credentials?: number;
  unpinned_projects?: Array<string>;
  running_work_items?: Array<string>;
  forced?: boolean;
};

export type AgentOwnerChange = {
  email: string;
};

/** A tool grant that binds the call's arguments (ADR 0128): `sync_application` on the application `shop` only. The call's arguments must satisfy `arguments` on top of the operation's input schema, and of the organisation's rule and the project's policy: all of them. A call outside is refused (400, problem `arguments_outside_grant`, naming the level and the JSON path). */
export type AgentToolGrant = {
  /** the operation, or a `prefix_*` pattern */
  name: string;
  /** a JSON Schema (2020-12, no $ref, no remote anything, at most 8 KiB); `{project}` is the run's project slug. It names only arguments the operation has, and the pattern must match an operation of an organisation connector (422 when the version is written) */
  arguments: {
    [key: string]: unknown;
  };
};

/** What a version reaches in a project (ADR 0127). */
export type AgentAccess = {
  agent: string;
  version: number;
  project: string;
  /** true when the version inherits nothing from its project */
  complete: boolean;
  /** the components the version leaves to its project */
  inherits: Array<AgentComponent>;
  model: AgentAccessModel;
  tools: Array<AgentAccessTool>;
  knowledge: Array<AgentAccessItem>;
  memories: Array<AgentAccessItem>;
};

export type AgentComponent = "instructions" | "model" | "tools" | "knowledge" | "memory";

/** `agent`: the version names it; `project`: the version leaves it to the project; `frame`: the platform's own, every run has it; `refused`: the version names it and will not get it here */
export type AgentAccessOrigin = "agent" | "project" | "frame" | "refused";

export type AgentAccessModel = {
  /** what the version (or, inherited, the workflow and the project) asks for: a model or `profile:<tier>` */
  requested: string;
  /** the model it resolves to in this project, null when it does not resolve */
  resolved?: string | null;
  origin: AgentAccessOrigin;
  reason?: string | null;
};

export type AgentAccessTool = {
  name: string;
  /** where the tool comes from: the platform's frame, the deployment catalogue, an extension, a connector through the broker, the governed web tools */
  source: "frame" | "catalogue" | "extension" | "connector" | "web";
  origin: AgentAccessOrigin;
  access?: "read" | "write" | "approval" | null;
  /** why a named tool is refused */
  reason?: string | null;
  outpost?: AgentAccessOutpost;
};

/** Where a connector tool reached through an outpost lives (ADR 0149 §10, amending ADR 0127 §6): the outpost, the alias of the endpoint in its policy file, and whether a call made now would be handed to an instance. Present on the tool of an `mcp-outpost` connector and on no other: a tool of a direct connector carries no `outpost` key. Read when the access is asked, never promised: a person reads before a run that a tool its agent names will not answer. */
export type AgentAccessOutpost = {
  /** the outpost's slug; null when the connector routes to no outpost of the organisation (a call is then refused `outpost_paused`). An outpost of another organisation is never named */
  name: string | null;
  /** the alias of the endpoint in the outpost's policy file, as the connector names it */
  endpoint: string;
  /** the outpost's status: a call is handed to it only while it is `active`; null when the connector routes to no outpost of the organisation */
  status: OutpostStatus | null;
  /** an active instance that serves the alias polled within the poll window: the presence the call's own route reads. false when none did (a call fails at once, `outpost_offline`), when the connector routes to no outpost of the organisation, and while outposts are switched off on the deployment */
  online: boolean;
};

export type AgentAccessItem = {
  /** a knowledge base's slug, or a memory binding as `scope:slug` */
  name: string;
  origin: AgentAccessOrigin;
  /** a memory binding's mode (`read`, `write`) */
  mode?: string | null;
  reason?: string | null;
};

