/** Why a ticket's interpreter died. The ticket will not move again without a restart. */
export type WorkflowFailure = {
  message: string;
  activity?: string | null;
  state?: string | null;
  at?: string | null;
};

export type WorkItem = {
  /** The ticket's fields (ADR 0031). */
  fields?: {
    [key: string]: unknown;
  };
  id: string;
  project_slug: string;
  tracker_key: string;
  title: string;
  body_snapshot?: string | null;
  url?: string | null;
  size?: Size | null;
  risk?: Risk | null;
  state: string;
  state_display?: string | null;
  /** How the current state ends the work item when it is terminal: `success`, `declined` (a request turned down) or `cancelled` (dropped); null while it can still move. */
  state_outcome?: "success" | "declined" | "cancelled" | null;
  workflow_name?: string | null;
  workflow_version?: number | null;
  temporal_wf_id?: string | null;
  /** The workflow's Temporal status, when requested and known. FAILED, TERMINATED or TIMED_OUT = the ticket is dead. */
  workflow_status?: string | null;
  failure?: WorkflowFailure | null;
  paused?: boolean;
  current_run?: RunSummary | null;
  pending_request?: HumanRequest | null;
  pr_url?: string | null;
  /** The repository the work item works on (ADR 0124): the one it is fixed to, else its `fields.repository`, else the project's primary; null for a project without a repository. */
  repository?: string | null;
  /** Whether the target is fixed (ADR 0124 §3): a step touched its repository, so `fields.repository` may no longer name another one. */
  repository_fixed?: boolean;
  totals: Totals;
  /** The budget given at launch or by the workflow (ADR 0047); the policy's applies otherwise. */
  budget_usd?: number | null;
  estimate?: CostEstimate | null;
  /** Who started the work item (ADR 0077): `person:<email>`, `mcp:<email>`, `tracker:<source>` for a webhook, `schedule:<name>`… Null for a work item from before S40-22. */
  initiated_by?: string | null;
  /** Who filed the work item, as its tracker names them: Jira's reporter (`Name <e-mail>`, the name alone when the site hides the e-mail), the author's login on GitHub or GitLab, the person's e-mail in the console. Personal data: empty in a redacted entry. Null for a work item from before it was recorded. */
  reporter?: string | null;
  /** The restricted knowledge bases its runs were served (ADR 0114), only ever added to. Reading the work item, its runs, artefacts and receipts needs reading every one of them; otherwise the detail answers 404 and a list shows it `redacted`. */
  restricted_knowledge?: Array<string>;
  /** True in a list when the caller does not read every base in `restricted_knowledge` (ADR 0114): only `id`, `project_slug`, `tracker_key`, `title`, `state`, `state_display`, `state_outcome`, `workflow_name`, `workflow_version`, `url`, dates and `restricted_knowledge` are filled; everything else is empty. */
  redacted?: boolean;
  created_at?: string;
  closed_at?: string | null;
};

export type Totals = {
  tokens_in?: number;
  tokens_out?: number;
  tokens_cached?: number;
  cost_usd?: number;
  cost_eur?: number;
  duration_s?: number;
  runs?: number;
  /** the model calls the gateway counted (S57-01, ADR 0122): a run's round trips, or a work item's summed over its runs; null when unknown (a run booked before S57-01, a remote agent, a gateway that cannot read a spend back, or a work item one such run belongs to) */
  requests?: number | null;
  /** how the cost was priced (ADR 0060) */
  priced_by?: "gateway" | "override" | "none" | null;
  /** the gateway's own figure when an override replaced it */
  gateway_cost_usd?: number | null;
  unmeasured?: boolean;
};

export type CostEstimate = {
  median_usd?: number | null;
  p80_usd?: number | null;
  sample_size?: number;
  over_p80?: boolean;
};

/** A webhook event a project received, and what the platform did with it (S42-06f). */
export type ReceivedEvent = {
  id: string;
  received_at: string;
  /** jira, github, gitlab, tekton, argocd, alertmanager, plugin:<plugin>/<server>, trigger:<name>, schedule:<name> */
  source: string;
  event_type: string;
  delivery_id?: string | null;
  /** `reopened`: an ended work item's ticket came back (reopened, its start label applied again, a trigger delivery for its key) and this event started its new pass (C1). */
  outcome: "created_work_item" | "started" | "signalled" | "boarded" | "labels_updated" | "ignored_no_item_key" | "ignored_not_agent_ready" | "already_open" | "refused" | "ignored" | "reopened";
  work_item_key?: string | null;
  work_item_id?: string | null;
  /** Built from typed fields only: key, label, from → to, PR number, conclusion. */
  summary: string;
};

/** A project's HTTP trigger (S56-01, ADR 0113); its token is never listed. */
export type Trigger = {
  name: string;
  url: string;
  workflow?: string | null;
  title: string;
  key?: string | null;
  labels?: Array<string>;
  fields?: {
    [key: string]: string;
  };
  /** A JSON pointer to the text, or texts, a payload must hold (S56-05). */
  when?: {
    [key: string]: unknown;
  };
  auth?: "token" | "signature";
  has_token: boolean;
  token_created_at?: string | null;
};

/** A trigger's new token and the signing secret derived from it (S56-04), shown once. */
export type TriggerToken = {
  name: string;
  url: string;
  token: string;
  /** The HMAC-SHA256 key of `X-Choregos-Signature`; it changes with the token. */
  signing_secret: string;
};

/** What a trigger call did; `outcome` is the received event's, absent on a replayed delivery. */
export type TriggerAck = {
  accepted: boolean;
  duplicate?: boolean;
  outcome?: "created_work_item" | "already_open" | "ignored" | "reopened" | null;
  work_item_id?: string | null;
  work_item_key?: string | null;
  workflow?: string | null;
};

